screening_id = frappe.form_dict.get("screening_id")
out = {}

if screening_id:
    # 1. Find Lab Results linked to this Screening
    lab_results = frappe.get_all("Lab Result", 
        filters={"hajj_screening": screening_id, "docstatus": ["<", 2]}, 
        fields=["name"]
    )

    all_rows = []
    for lr in lab_results:
        lr_doc = frappe.get_doc("Lab Result", lr.name)
        if lr_doc.normal_test_items:
            all_rows.extend(lr_doc.normal_test_items)

    processed_grouped = set()
    processed_compound = set()

    def add_row(dept, rowdict):
        if dept not in out: out[dept] = []
        out[dept].append(rowdict)

    def get_template(name):
        if not name: return None
        name = name.strip()
        if frappe.db.exists("Lab Test Template", name):
            return frappe.get_cached_doc("Lab Test Template", name)
        return None

    # 2. Logic to group by department and handle template types
    for r in all_rows:
        tpl_name = (r.template or r.test or r.lab_test_name or "").strip()

        # --- REMOVE CBC TEMPLATE HERE ---
        if tpl_name == "CBC":
            continue
        # -------------------------------

        tpl = get_template(tpl_name)
        dept = (tpl.department or "Lab").strip() if tpl else "Other"
        tpl_type = (tpl.lab_test_template_type or "Single").strip() if tpl else "Single"

        if tpl_type == "Grouped":
            parent = (r.test or tpl.name).strip()
            # Double check parent name is not CBC
            if parent == "CBC": continue

            if parent not in processed_grouped:
                add_row(dept, {"is_header": True, "name": parent})
                processed_grouped.add(parent)
            add_row(dept, {"is_header": False, "name": r.lab_test_name or r.lab_test_event, "result": r.result_value, "uom": r.lab_test_uom, "range": r.normal_range})

        elif tpl_type == "Compound":
            if not tpl or tpl.name == "CBC" or tpl.name in processed_compound: 
                continue

            add_row(dept, {"is_header": True, "name": tpl.lab_test_name or tpl.name})
            comp_rows = [x for x in all_rows if (x.template == tpl.name or x.test == tpl.name)]
            for x in comp_rows:
                add_row(dept, {"is_header": False, "name": x.lab_test_event or x.lab_test_name, "result": x.result_value, "uom": x.lab_test_uom, "range": x.normal_range})
            processed_compound.add(tpl.name)

        else:
            add_row(dept, {"is_header": False, "name": r.lab_test_name or (tpl.lab_test_name if tpl else "Unknown"), "result": r.result_value, "uom": r.lab_test_uom, "range": r.normal_range})

